  // Firefox: "functionName@file.js:1:2"
  const regex = /(?:at\s+(.+?)\s+\()?(?:(.+?)@)?([^@\s()]+):(\d+):(\d+)/;
  return stack.split('\n').map(line => {
    const match = line.match(regex);
    if (!match) return null; // Skip if line format is invalid

    // Chrome: match[1], Firefox: match[2]
