    renderTarget.texture.name = 'output';
    renderTarget.depthTexture = depthTexture;

    /**
     * The pass's render target.
     *
     * @type {RenderTarget}
     */
    this.renderTarget = renderTarget;

    /**
     * An optional override material for the pass.
     *
     * @type {Material|null}
     */
