     * Whether the pass is transparent.
     *
     * @type {boolean}
     * @default false
     */
    this.transparent = true;

    /**
     * Whether the pass is opaque.
     *
     * @type {boolean}
     * @default true
     */
    this.opaque = true;

    /**
     * An optional global context for the pass.
     *
     * @type {ContextNode|null}
     */
    this.contextNode = null;

    /**
     * A cache for the context node.
     *
     * @private
     * @type {?Object}
     * @default null
