     * to produce the pass.
     *
     * @private
     * @type {?Layers}
     * @default null
     */
    this._layers = null;

    /**
     * Scales the resolution of the internal render target.
     *
     * @private
     * @type {number}
     * @default 1
     */
    this._resolutionScale = 1;

    /**
     * Custom viewport definition.
     *
     * @private
     * @type {?Vector4}
     * @default null
     */
    this._viewport = null;

    /**
     * Custom scissor definition.
     *
     * @private
     * @type {?Vector4}
     * @default null
