    if (viewZNode === undefined) {
      const cameraNear = this._cameraNear;
      const cameraFar = this._cameraFar;
      this._viewZNodes[name] = viewZNode = perspectiveDepthToViewZ(this.getTextureNode(name), cameraNear, cameraFar);
